# Extract all exported function and method names with file paths
grep -rn '^func ' /bench/repo/internal/ --include='*.go' | grep -v '_test.go' | sed 's/:/ /' | awk '{
    file=$1;
    # Find the function name
    for(i=2;i<=NF;i++) {
        if($i ~ /^[A-Z]/) {
            fname=$i;
            sub(/\(.*/, "", fname);
            print fname "\t" file;
            break;
        }
    }
}' | sort -u

